      ex: { prompt: 'Write citationCoverage(sentences) where sentences are { text, sources }. Return { coveredPct, uncited }: coveredPct is the percentage of sentences with at least one source, rounded to the nearest integer (0 if there are no sentences); uncited lists the indices of sentences with no sources.', fn: 'citationCoverage', params: 'sentences', cases: [{ args: [[{ text: 'Revenue rose 4%.', sources: ['q3.pdf'] }, { text: 'Costs fell.', sources: [] }, { text: 'Margin hit 21%.', sources: ['q3.pdf', 'q4.pdf'] }]], expect: { coveredPct: 67, uncited: [1] } }, { args: [[]], expect: { coveredPct: 0, uncited: [] } }], solution: `function citationCoverage(s){if(!s.length)return{coveredPct:0,uncited:[]};const uncited=s.map((x,i)=>x.sources.length?-1:i).filter(i=>i>=0);return{coveredPct:Math.round((s.length-uncited.length)/s.length*100),uncited}}`, hint: 'Find uncited indices, then compute the percentage.' },
